-- ============================================================================
-- seed_etl_run_config_FSS.sql  (FSS step-driver package)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflow wf_FSS_Stage_Load: one row
-- per driver row (STEP_NO = 0, IS_DRIVER = 'Y') + every transform step +
-- every publish branch.  All IS_RUN_ENABLED = 'Y' (everything runs).
-- The DELETE below removes FSS workflow rows only, so re-running this seed is safe.
-- Run it in the COMMON schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are informational
-- for a driver run -- gating is by IS_RUN_ENABLED only. The driver does NOT
-- validate flag consistency. Publish branches take the current publish
-- step number (50), then +10 each.
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME = 'wf_FSS_Stage_Load';


-- 50 rows: 6 driver rows + 21 steps + 23 publish branches.
